        }
        if (table[h] == EMPTY)
            printf("key=%d not found, cmp=%d\n", key, cmp);
    }
    return 0;
}

#include <stdio.h>

#define N 7

/* 折半查找，返回比较次数（正数=成功，负数=失败但绝对值是比较次数） */
static int binSearch(const int *a, int n, int key)
{
    int low = 0, high = n - 1, mid, cmp = 0;

    while (low <= high) {
        mid = low + (high - low) / 2;
        cmp++;
        if (a[mid] == key) return cmp;
        if (a[mid] < key) low = mid + 1;
        else high = mid - 1;
    }
    return -cmp;
}

/* 顺序查找（a[1..n]，a[0] 是哨兵），返回比较次数 */
static int seqSearch(int *a, int n, int key)
{
    int i, cmp = 0;

    a[0] = key;
    for (i = n; a[i] != key; i--) cmp++;
    cmp++;                       /* 命中那一次 */
    return cmp;
}

int main(void)
{
    int a[N + 1], level[N + 1], cntAtLevel[N + 2];
    /* 三种概率分布，都以 1/28 为单位，各自求和恰好 28 */
    int pEq[N]  = {4, 4, 4, 4, 4, 4, 4};
    int pMid[N] = {4, 3, 2, 8, 2, 3, 6};
    int pEnd[N] = {8, 3, 2, 4, 2, 3, 6};
    int i, j, r, sumLevel, h;
    double aslSeq, aslBin;

    a[0] = 0;
    for (i = 1; i <= N; i++) a[i] = 3 * i + 4;   /* 7 10 13 16 19 22 25 */

    printf("有序表 a[1..%d] = ", N);
    for (i = 1; i <= N; i++) printf("%d ", a[i]);
    printf("\n");

    /* ── 判定树：每个元素在第几层被找到 ── */
    printf("\n== 折半查找的判定树 ==\n");
    for (i = 0; i <= N + 1; i++) cntAtLevel[i] = 0;
    h = 0;
    for (i = 1; i <= N; i++) {
        r = binSearch(a + 1, N, a[i]);
        level[i] = r;
        cntAtLevel[r]++;
        if (r > h) h = r;
    }
    printf("  各元素所在的层：");
    for (i = 1; i <= N; i++) printf("a[%d]=%d在第%d层 ", i, a[i], level[i]);
    printf("\n  各层结点个数：");
    for (j = 1; j <= h; j++) printf("第%d层=%d个 ", j, cntAtLevel[j]);
    printf("\n  判定树高度 h = %d，⌈log2(n+1)⌉ = ⌈log2 8⌉ = 3 相符=%d\n", h, h == 3);
    sumLevel = 0;
    for (i = 1; i <= N; i++) sumLevel += level[i];
    printf("  Σ层数 = %d，等概率 ASL_成功 = %d/%d = %.4f\n", sumLevel, sumLevel, N,
           (double)sumLevel / N);

    /* ── 三种概率分布下的 ASL ── */
    printf("\n== 三种概率分布下的 ASL 对照（概率以 1/28 为单位）==\n");
    printf("  分布①等概率      p = ");
    for (i = 0; i < N; i++) printf("%d ", pEq[i]);
    printf("\n  分布②集中在中间  p = ");
    for (i = 0; i < N; i++) printf("%d ", pMid[i]);
    printf("\n  分布③集中在端点  p = ");
    for (i = 0; i < N; i++) printf("%d ", pEnd[i]);
    printf("\n\n");

    {
        int *dists[3];
        const char *names[3];
        int k, numSeq, numBin;

        dists[0] = pEq;  names[0] = "等概率    ";
        dists[1] = pMid; names[1] = "集中中间  ";
        dists[2] = pEnd; names[2] = "集中端点  ";
        for (k = 0; k < 3; k++) {
            int *p = dists[k];

            numSeq = 0;
            numBin = 0;
            for (i = 0; i < N; i++) {
                numSeq += p[i] * (i + 1);            /* 顺序查找：第 i+1 个元素比较 i+1 次 */
                numBin += p[i] * level[i + 1];       /* 折半查找：比较 level 次 */
            }
            aslSeq = (double)numSeq / 28;
            aslBin = (double)numBin / 28;
            printf("  %s：ASL_顺序 = %3d/28 = %.4f   ASL_折半 = %3d/28 = %.4f   折半更优=%d\n",
                   names[k], numSeq, aslSeq, numBin, aslBin, aslBin < aslSeq);
        }
    }

    /* ── 失败 ASL ── */
    printf("\n== 失败时的 ASL ==\n");
    {
        int failKeys[N + 1], totalSeq = 0, totalBin = 0;

        /* n=7 有 8 个失败区间：小于最小、6 个间隙、大于最大 */
        failKeys[0] = 1;
        for (i = 1; i < N; i++) failKeys[i] = a[i] + 1;      /* 落在 a[i] 与 a[i+1] 之间 */
        failKeys[N] = a[N] + 1;
        for (i = 0; i <= N; i++) {
            r = seqSearch(a, N, failKeys[i]);
            totalSeq += r;
            r = binSearch(a + 1, N, failKeys[i]);
            totalBin += -r;
        }
        printf("  8 个失败键：");
        for (i = 0; i <= N; i++) printf("%d ", failKeys[i]);
        printf("\n  顺序查找 ASL_失败 = %d/8 = %.4f（公式 n+1 = %d）\n",
               totalSeq, (double)totalSeq / 8, N + 1);
        printf("  折半查找 ASL_失败 = %d/8 = %.4f\n", totalBin, (double)totalBin / 8);
    }

    printf("\n演示结束\n");
    return 0;
}

#include <stdio.h>

#define N 15

/* ① 从前往后，不带哨兵。keyCmp 与 boundCmp 分别统计两类判断的次数 */
static int seqFront(const int *a, int n, int key, int *keyCmp, int *boundCmp)
{
    int i;

    *keyCmp = 0;
    *boundCmp = 0;
    for (i = 0; i < n; i++) {
        (*boundCmp)++;
        if (a[i] == key) { (*keyCmp)++; return i; }
        (*keyCmp)++;
    }
    return -1;
}

/* ② 从后往前 + 哨兵（a[0] 是哨兵位，数据在 a[1..n]） */
static int seqSentinel(int *a, int n, int key, int *keyCmp)
{
    int i;

    *keyCmp = 0;
    a[0] = key;
    for (i = n; a[i] != key; i--) (*keyCmp)++;
    (*keyCmp)++;
    return i;
}

/* ③ 有序表：a[i] > key 时提前终止失败
   同时统计「关键字比较」与「越界判断」两类次数——教材公式 n/2+1 把终止时的
   那次 i<n 越界判断也算进去，只数关键字比较会少 1/(n+1) */
static int seqSortedEarly(const int *a, int n, int key, int *keyCmp, int *boundCmp, int *early)
{
    int i;

    *keyCmp = 0;
    *boundCmp = 0;
    *early = 0;
    for (i = 0; i < n; i++) {
        (*boundCmp)++;
        (*keyCmp)++;
        if (a[i] == key) return i;
        if (a[i] > key) { *early = 1; return -1; }   /* ★ 提前终止 */
    }
    (*boundCmp)++;                 /* 循环因 i < n 为假而结束，这也是一次判断 */
    return -1;
}

int main(void)
{
    int a[N + 1];
    int i, r, kc, bc, early;
    int totalNoSentinel = 0, totalSentinel = 0;
    int totalSucc = 0, totalFailPlain = 0, totalFailEarly = 0, earlyHit = 0;
    int totalFailEarlyB = 0, plain, ec, eb;
    int failKeys[N + 1];

    a[0] = 0;
    for (i = 1; i <= N; i++) a[i] = 2 * i;          /* 2 4 6 … 30，有序 */

    printf("有序表 a[1..%d] = ", N);
    for (i = 1; i <= N; i++) printf("%d ", a[i]);
    printf("\n");

    /* ── ① 哨兵的操作计数：查遍全部 15 个成功键 ── */
    printf("\n== 哨兵的作用：查遍全部 %d 个成功键 ==\n", N);
    for (i = 1; i <= N; i++) {
        r = seqFront(a + 1, N, a[i], &kc, &bc);
        totalNoSentinel += kc + bc;
        r = seqSentinel(a, N, a[i], &kc);
        totalSentinel += kc;
    }
    printf("  不带哨兵：关键字比较 + 越界判断合计 = %d 次\n", totalNoSentinel);
    printf("  带哨兵  ：只有关键字比较           = %d 次\n", totalSentinel);
    printf("  正好减半 = %d（理论值 n(n+1) = %d 与 n(n+1)/2 = %d）\n",
           totalNoSentinel == 2 * totalSentinel, N * (N + 1), N * (N + 1) / 2);

    /* ASL_成功（只数关键字比较） */
    totalSucc = 0;
    for (i = 1; i <= N; i++) { seqSentinel(a, N, a[i], &kc); totalSucc += kc; }
    printf("  ASL_成功 = %d/%d = %.4f（公式 (n+1)/2 = %.4f）相符=%d\n",
           totalSucc, N, (double)totalSucc / N, (N + 1) / 2.0,
           (double)totalSucc / N == (N + 1) / 2.0);

    /* ── ② 失败 ASL：普通 vs 有序提前终止 ── */
    printf("\n== 失败 ASL：普通顺序查找 vs 有序表提前终止 ==\n");
    failKeys[0] = 1;                                 /* 小于最小 */
    for (i = 1; i < N; i++) failKeys[i] = a[i] + 1;  /* 落在间隙里 */
    failKeys[N] = a[N] + 1;                          /* 大于最大 */
    printf("  %d 个失败键：", N + 1);
    for (i = 0; i <= N; i++) printf("%d ", failKeys[i]);
    printf("\n");

    for (i = 0; i <= N; i++) {
        /* 先把结果存进局部量再 printf：seqSentinel 会改 a[0]，
           把它直接放进 printf 的实参里就会与 kc 的求值顺序打架 */
        r = seqSentinel(a, N, failKeys[i], &kc);
        plain = kc;
        totalFailPlain += plain;

        seqSortedEarly(a + 1, N, failKeys[i], &ec, &eb, &early);
        totalFailEarly += ec;
        totalFailEarlyB += eb;
        if (early) earlyHit++;

        printf("    key=%2d：哨兵版返回 %2d 比较 %2d 次 | 提前终止版 关键字 %2d 次 越界 %2d 次%s\n",
               failKeys[i], r, plain, ec, eb,
               early ? "（a[i] > key 提前退出）" : "（走到表尾）");
    }
    printf("  ASL_失败（哨兵版，只数关键字比较）      = %d/%d = %.4f（公式 n+1 = %d）\n",
           totalFailPlain, N + 1, (double)totalFailPlain / (N + 1), N + 1);
    printf("  ASL_失败（提前终止，只数关键字比较）    = %d/%d = %.4f\n",
           totalFailEarly, N + 1, (double)totalFailEarly / (N + 1));
    printf("  ASL_失败（提前终止，含终止时的越界判断）= %d/%d = %.4f（公式 n/2+1 = %.4f）相符=%d\n",
           totalFailEarlyB, N + 1, (double)totalFailEarlyB / (N + 1), N / 2.0 + 1,
           (double)totalFailEarlyB / (N + 1) == N / 2.0 + 1);
    printf("  提前终止生效的键有 %d 个（只有 key=%d 大于全部元素，必须走到表尾）\n",
           earlyHit, failKeys[N]);

    printf("\n演示结束\n");
    return 0;
}

#include <stdio.h>

#define N 15

/* 正确写法：low <= high，mid = low + (high-low)/2 */
static int binOK(const int *a, int n, int key, int *cmp)
{
    int low = 0, high = n - 1, mid;

    *cmp = 0;
    while (low <= high) {
        mid = low + (high - low) / 2;
        (*cmp)++;
        if (a[mid] == key) return mid;
        if (a[mid] < key) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

/* 错误写法一：low < high。★ 注意末尾没有任何补救——
   这正是它「漏查」的原因：low == high 时区间里还剩一个候选元素没比较就退出了 */
static int binBadCond(const int *a, int n, int key, int *cmp)
{
    int low = 0, high = n - 1, mid;

    *cmp = 0;
    while (low < high) {
        mid = low + (high - low) / 2;
        (*cmp)++;
        if (a[mid] == key) return mid;
        if (a[mid] < key) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

/* 错误写法二：low = mid（不加 1）→ 死循环，这里加轮数上限来暴露它 */
static int binBadStep(const int *a, int n, int key, int *cmp, int *stuck)
{
    int low = 0, high = n - 1, mid, guard = 0;

    *cmp = 0;
    *stuck = 0;
    while (low <= high) {
        if (++guard > 4 * n) { *stuck = 1; return -1; }   /* 轮数超限 = 区间没缩小 */
        mid = low + (high - low) / 2;
        (*cmp)++;
        if (a[mid] == key) return mid;
        if (a[mid] < key) low = mid;              /* ✗ 少了 +1 */
        else high = mid - 1;
    }
    return -1;
}

