    printf("\n== 判定树 ==\n");
    for (i = 0; i <= N + 1; i++) { cntAtLevel[i] = 0; failLevel[i] = 0; }
    for (i = 0; i < N; i++) {
        r = binOK(a, N, a[i], &cmp);
        cntAtLevel[cmp]++;
        sumSucc += cmp;
        if (cmp > h) h = cmp;
        printf("  key=%2d 在下标 %2d 找到，比较 %d 次\n", a[i], r, cmp);
    }
    printf("  各层结点个数：");
    for (i = 1; i <= h; i++) printf("第%d层=%d ", i, cntAtLevel[i]);
    printf("\n  合计 = %d（应等于 n=%d）相符=%d\n",
           cntAtLevel[1] + cntAtLevel[2] + cntAtLevel[3] + cntAtLevel[4] + cntAtLevel[5],
           N,
           cntAtLevel[1] + cntAtLevel[2] + cntAtLevel[3] + cntAtLevel[4] + cntAtLevel[5] == N);
    printf("  树高 h = %d，⌈log2(n+1)⌉ = ⌈log2 16⌉ = 4 相符=%d\n", h, h == 4);
    printf("  ASL_成功 = %d/%d = %.4f（近似公式 log2(n+1)-1 = 3.0000）\n",
           sumSucc, N, (double)sumSucc / N);

    /* ── ② 失败 ASL：n+1 = 16 个失败区间 ── */
    printf("\n== 失败查找：%d 个失败区间 ==\n", N + 1);
    failKeys[0] = 1;
    for (i = 1; i < N; i++) failKeys[i] = a[i - 1] + 1;
    failKeys[N] = a[N - 1] + 1;
    for (i = 0; i <= N; i++) {
        r = binOK(a, N, failKeys[i], &cmp);
        failLevel[cmp]++;
        sumFail += cmp;
        printf("  key=%2d 未找到（返回 %d），比较 %d 次\n", failKeys[i], r, cmp);
    }
    printf("  失败比较次数的分布：");
    for (i = 1; i <= h + 1; i++) if (failLevel[i] > 0) printf("%d次=%d个 ", i, failLevel[i]);
    printf("\n  ASL_失败 = %d/%d = %.4f\n", sumFail, N + 1, (double)sumFail / (N + 1));

    /* ── ③ 两个经典错误写法 ── */
    printf("\n== 错误写法对照 ==\n");
    r = binOK(a, N, a[N - 1], &cmp);
    printf("  查最后一个元素 key=%d：正确写法 → 下标 %d，比较 %d 次\n", a[N - 1], r, cmp);
    r = binBadCond(a, N, a[N - 1], &cmp);
    printf("  查最后一个元素 key=%d：low<high → 下标 %d（-1 表示漏查）比较 %d 次\n",
           a[N - 1], r, cmp);
    r = binBadCond(a, 1, a[0], &cmp);
    printf("  n=1 的表查它唯一的元素：low<high → 下标 %d（明明存在却说找不到）\n", r);

    r = binBadStep(a, N, a[N - 1], &cmp, &stuck);
    printf("  low = mid（少 +1）查 key=%d：卡死=%d 比较次数=%d（轮数超过上限 4n=%d 才被迫退出）\n",
           a[N - 1], stuck, cmp, 4 * N);

    /* ── ④ mid 的溢出防线 ── */
    /* ── ④ mid 的溢出防线 ──
       这里刻意用 double 算出真实的和，而不是真的让 int 溢出：
       有符号整数溢出在 C 里是未定义行为，输出不可复现，不能拿来出题 */
    printf("\n== mid 的两种写法（用 double 算出真实的和，避免真的触发有符号溢出）==\n");
    sum = (double)lo + (double)hi;
    printf("  下标 low=%d high=%d 时：\n", lo, hi);
    printf("    (low+high)/2 需要 low+high = %.0f，超出 int 上限 2147483647 → 溢出成负下标\n", sum);
    printf("    low+(high-low)/2 = %d，始终在 int 范围内 → 正确\n", lo + (hi - lo) / 2);

    printf("\n演示结束\n");
    return 0;
}

#include <stdio.h>

#define N   16
#define MAXS 16           /* 每块的容量上限，留余量给插入演示 */

/* 一块：块内元素 + 实际长度 + 本块最大关键字 */
typedef struct {
    int elem[MAXS];
    int len;
    int maxKey;
} Block;

/* 按块长 s 把有序表 a[0..n-1] 切成若干块 */
static int buildBlocks(const int *a, int n, int s, Block *blk)
{
    int i, j, k = 0;

    for (i = 0; i < n; i += s) {
        blk[k].len = 0;
        blk[k].maxKey = a[i];
        for (j = i; j < n && j < i + s; j++) {
            blk[k].elem[blk[k].len++] = a[j];
            if (a[j] > blk[k].maxKey) blk[k].maxKey = a[j];
        }
        k++;
    }
    return k;                          /* 返回块数 b */
}

/* 索引表是否升序（等价于「块间有序」是否成立） */
static int indexSorted(const Block *blk, int b)
{
    int i;

    for (i = 1; i < b; i++)
        if (blk[i - 1].maxKey >= blk[i].maxKey) return 0;
    return 1;
}

/* 顺序查索引 + 块内顺序查。返回 1=找到，cmpI 与 cmpS 是两步的比较次数 */
static int blockSeq(const Block *blk, int b, int key, int *cmpI, int *cmpS, int *outBlk, int *outPos)
{
    int i, j;

    *cmpI = 0;
    *cmpS = 0;
    for (i = 0; i < b; i++) {
        (*cmpI)++;
        if (key <= blk[i].maxKey) break;      /* 第一个 maxKey >= key 的块 */
    }
    if (i >= b) return 0;                     /* key 大于所有块的最大值 */
    for (j = 0; j < blk[i].len; j++) {
        (*cmpS)++;
        if (blk[i].elem[j] == key) { *outBlk = i; *outPos = j; return 1; }
    }
    return 0;
}

/* 折半查索引（lower_bound：第一个 maxKey >= key 的块）+ 块内顺序查 */
static int blockBin(const Block *blk, int b, int key, int *cmpI, int *cmpS, int *outBlk, int *outPos)
{
    int low = 0, high = b - 1, mid, i, j;

    *cmpI = 0;
    *cmpS = 0;
    while (low <= high) {
        mid = low + (high - low) / 2;
        (*cmpI)++;
        if (key <= blk[mid].maxKey) high = mid - 1;
        else low = mid + 1;
    }
    i = low;
    if (i >= b) return 0;
    for (j = 0; j < blk[i].len; j++) {
        (*cmpS)++;
        if (blk[i].elem[j] == key) { *outBlk = i; *outPos = j; return 1; }
    }
    return 0;
}

/* 折半查找在长度 n 的有序表上的「成功 ASL」：逐个键实测，不用 log 近似公式。
   虚拟表取 a[i] = i，所以只需比较下标，不必真的建表。 */
static double binASL(int n)
{
    long long total = 0;
    int key;

    for (key = 0; key < n; key++) {
        int low = 0, high = n - 1, cnt = 0;

        while (low <= high) {
            int mid = low + (high - low) / 2;

            cnt++;
            if (mid == key) break;
            if (key < mid) high = mid - 1;
            else low = mid + 1;
        }
        total += cnt;
    }
    return (double)total / n;
}

